#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long row[61] = {0};
    row[0] = 1;
    for (int r = 0; r < n; ++r) {
        row[r] = 1; // set the last element of the current row
        for (int c = r - 1; c > 0; --c) {
            row[c] = row[c] + row[c - 1];
        }
        for (int c = 0; c <= r; ++c) {
            if (c) putchar(' ');
            printf("%lld", row[c]);
        }
        putchar('\n');
    }
    return 0;
}
